using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using Office=Microsoft.Office.Core;
using PowerPoint=Microsoft.Office.Interop.PowerPoint;
namespace PowerPointIntelligence.AddIn {
 internal sealed class FontSelectionState {internal string Family;internal float? Size;internal bool? Bold,Italic;internal int TargetCount,CharacterCount;}
 internal static class ContextFontPlan {
  internal static void Validate(string family,float? size,bool? bold,bool? italic){if(family!=null&&(String.IsNullOrWhiteSpace(family)||family.Length>128||family.Any(Char.IsControl)))throw new InvalidDataException("Font family must contain 1 to 128 printable characters.");if(size.HasValue&&(Single.IsNaN(size.Value)||Single.IsInfinity(size.Value)||size<1||size>4000))throw new InvalidDataException("Font size must be between 1 and 4,000 points.");if(family==null&&!size.HasValue&&!bold.HasValue&&!italic.HasValue)throw new InvalidDataException("Choose at least one font property.");}
  internal static FontSelectionState Merge(IEnumerable<FontSelectionState> states){var list=states.ToArray();if(list.Length==0)throw new InvalidDataException("No native font targets.");var first=list[0];return new FontSelectionState{Family=list.All(x=>String.Equals(x.Family,first.Family,StringComparison.Ordinal))?first.Family:null,Size=list.All(x=>x.Size==first.Size)?first.Size:null,Bold=list.All(x=>x.Bold==first.Bold)?first.Bold:null,Italic=list.All(x=>x.Italic==first.Italic)?first.Italic:null,TargetCount=list.Sum(x=>x.TargetCount),CharacterCount=list.Sum(x=>x.CharacterCount)};}
 }
 internal static class ContextFormatting {
  sealed class Collector {internal int Nodes,Characters,Depth;internal readonly List<PowerPoint.TextRange> Ranges=new List<PowerPoint.TextRange>();}
  static void Add(Collector plan,PowerPoint.Shape shape,int depth,bool tableCell=false){if(++plan.Nodes>NativeFormattingPlan.MaxTargets||depth>NativeFormattingPlan.MaxDepth)throw new InvalidDataException("Font selection exceeds native formatting limits.");plan.Depth=Math.Max(plan.Depth,depth);foreach(float n in new[]{shape.Left,shape.Top,shape.Width,shape.Height})if(Single.IsNaN(n)||Single.IsInfinity(n)||Math.Abs(n)>100000)throw new InvalidDataException("Invalid shape bounds.");if(tableCell){Range(plan,shape.TextFrame.TextRange);return;}if(shape.Type==Office.MsoShapeType.msoGroup){foreach(PowerPoint.Shape child in shape.GroupItems)Add(plan,child,depth+1);return;}if(shape.HasTable==Office.MsoTriState.msoTrue){var table=shape.Table;int rows=table.Rows.Count,cols=table.Columns.Count;if((long)rows*cols>400)throw new InvalidDataException("Font formatting supports tables with at most 400 cells.");bool selected=false;for(int r=1;r<=rows;r++)for(int c=1;c<=cols;c++)if(table.Cell(r,c).Selected)selected=true;for(int r=1;r<=rows;r++)for(int c=1;c<=cols;c++)if(!selected||table.Cell(r,c).Selected)Add(plan,table.Cell(r,c).Shape,depth+1,true);return;}if(depth>0&&shape.HasTextFrame!=Office.MsoTriState.msoTrue)return;if(shape.Type!=Office.MsoShapeType.msoAutoShape&&shape.Type!=Office.MsoShapeType.msoTextBox&&shape.Type!=Office.MsoShapeType.msoFreeform&&shape.Type!=Office.MsoShapeType.msoPlaceholder)throw new InvalidOperationException("Select native text shapes or table cells; pictures, charts, lines and embedded objects are not font targets.");if(shape.HasTextFrame!=Office.MsoTriState.msoTrue)throw new InvalidOperationException("Every selected shape must have native editable text.");Range(plan,shape.TextFrame.TextRange);}
  static void Range(Collector plan,PowerPoint.TextRange range){plan.Characters+=range.Length;if(plan.Characters>NativeFormattingPlan.MaxCharacters)throw new InvalidDataException("Select at most 2,000 text characters.");plan.Ranges.Add(range);}
  static Collector Collect(PowerPoint.Application app){if(!NativeFormatting.CanApply(app))throw new InvalidOperationException("Select native text in Normal view.");var plan=new Collector();var selection=app.ActiveWindow.Selection;if(selection.Type==PowerPoint.PpSelectionType.ppSelectionText){plan.Nodes=1;Range(plan,selection.TextRange);}else{if(NativeFormatting.SelectedShapes(selection).Count>500)throw new InvalidDataException("Select at most 500 native targets.");foreach(PowerPoint.Shape shape in NativeFormatting.SelectedShapes(selection))Add(plan,shape,0);}NativeFormattingPlan.Bounds(plan.Nodes,plan.Characters,plan.Depth);if(plan.Ranges.Count==0)throw new InvalidOperationException("The selected group has no editable native text.");return plan;}
  static IEnumerable<PowerPoint.Font> Fonts(Collector plan){foreach(var range in plan.Ranges){if(range.Length==0)yield return range.Font;else for(int i=1;i<=range.Length;i++)yield return range.Characters(i,1).Font;}}
  static bool? Flag(Office.MsoTriState value){return value==Office.MsoTriState.msoTrue?(bool?)true:value==Office.MsoTriState.msoFalse?(bool?)false:null;}
  internal static FontSelectionState Read(PowerPoint.Application app){var plan=Collect(app);var merged=ContextFontPlan.Merge(Fonts(plan).Select(font=>new FontSelectionState{Family=String.IsNullOrEmpty(font.Name)?null:font.Name,Size=font.Size>0?(float?)font.Size:null,Bold=Flag(font.Bold),Italic=Flag(font.Italic)}));merged.TargetCount=plan.Ranges.Count;merged.CharacterCount=plan.Characters;return merged;}
  internal static void ApplyFont(PowerPoint.Application app,string family,float? size,bool? bold,bool? italic){ContextFontPlan.Validate(family,size,bold,italic);var plan=Collect(app);var changes=new List<NativeFormattingChange>();foreach(var font in Fonts(plan)){// Snapshot individual characters, never a flattened mixed TextRange font.
   if(family!=null){string old=font.Name;if(String.IsNullOrEmpty(old))throw new InvalidDataException("Cannot preserve an unknown font family.");changes.Add(new NativeFormattingChange(()=>font.Name=family,()=>font.Name=old));}
   if(size.HasValue){float old=font.Size;if(old<=0||Single.IsNaN(old)||Single.IsInfinity(old))throw new InvalidDataException("Cannot preserve mixed or invalid character font size.");changes.Add(new NativeFormattingChange(()=>font.Size=size.Value,()=>font.Size=old));}
   if(bold.HasValue){var old=font.Bold;if(!Flag(old).HasValue)throw new InvalidDataException("Cannot preserve mixed character bold state.");changes.Add(new NativeFormattingChange(()=>font.Bold=bold.Value?Office.MsoTriState.msoTrue:Office.MsoTriState.msoFalse,()=>font.Bold=old));}
   if(italic.HasValue){var old=font.Italic;if(!Flag(old).HasValue)throw new InvalidDataException("Cannot preserve mixed character italic state.");changes.Add(new NativeFormattingChange(()=>font.Italic=italic.Value?Office.MsoTriState.msoTrue:Office.MsoTriState.msoFalse,()=>font.Italic=old));}
  }app.StartNewUndoEntry();NativeFormattingTransaction.Run(changes);}
 }
}

